let totalKits = 0;
let totalPruebasU = 0;
const fefoCounts = { vencidos: 0, menos30: 0, menos90: 0, mas90: 0 };
const marcasStock = {};
const productosStock = {};
const equiposSeriesMap = {}; // Deduplicación inteligente de números de serie para analizadores físicos
const hoy = new Date();

const lotesAudit = rows.map((r, idx) => {
  const d = r.json;
  const kits = Number(d['Qty Kit'] || d.Qty_Kit || d.Kits || d.Cantidad || 0);
  const pruebasU = Number(d['Qty U'] || d.Qty_U || d.Pruebas || d.Unidades || (kits * 50));
  const rawMarca = String(d.Marca || d.Brand || 'Genérica').trim();
  const sku = String(d.ProductoID || d.ProductID || d.CodFabID || d.SKU || ('SKU-' + (idx + 1))).trim();
  const rawNombre = d.Producto || d.Description || d.Nombre;
  const prod = skuMap[sku] || (rawNombre && rawNombre !== 'N/A' ? String(rawNombre).trim() : 'Reactivo Diagnóstico');
  const rawLote = String(d.Lote || d.Batch || 'N/A').trim();

  // Normalización 3FN: Detecci����������n inteligente de analizadores físicos (Hardware) vs Reactivos Perecederos
  const esEquipo = rawMarca.toLowerCase().includes('equipo') || (kits === 0 && pruebasU === 1 && !d.FechaVence);
  const marcaLimpia = rawMarca.replace(/\s+Equipo$/i, '').trim();

  totalKits += kits;
  totalPruebasU += pruebasU;

  marcasStock[marcaLimpia] = (marcasStock[marcaLimpia] || 0) + (kits > 0 ? kits : pruebasU);

  // Registro en catálogo consolidado único
  if (!productosStock[sku]) {
    productosStock[sku] = {
      sku,
      producto: prod,
      marca: marcaLimpia,
      es_equipo: esEquipo,
      kits: 0,
      pruebasU: 0,
      lotes: [],
      series: []
    };
  }
  productosStock[sku].kits += kits;
  productosStock[sku].pruebasU += pruebasU;

  // Si es analizador/equipo, registrar el número de serie individual
  if (esEquipo && rawLote && rawLote !== 'N/A') {
    if (!equiposSeriesMap[sku]) equiposSeriesMap[sku] = [];
    equiposSeriesMap[sku].push({
      numero_serie: rawLote,
      fecha_ingreso: d.FechaTransac || '2025-03-31',
      estado: 'En Bodega'
    });
    productosStock[sku].series.push(rawLote);
  }

  // Si es reactivo perecedero, calcular días de vencimiento FEFO
  let dias = 180;
  let venceStr = '31/12/2026';
  try {
    const rawVence = d.FechaVence || d.Fecha_Vencimiento || d.Vence || d.Caducidad;
    if (rawVence) {
      const parts = String(rawVence).split(/[-/]/);
      if (parts.length === 3) {
        const vDate = parts[0].length === 4 ? new Date(parts[0], parts[1]-1, parts[2]) : new Date(parts[2], parts[1]-1, parts[0]);
        if (!isNaN(vDate.getTime())) {
          dias = Math.round((vDate.getTime() - hoy.getTime()) / (1000 * 60 * 60 * 24));
          venceStr = String(rawVence);
        }
      }
    }
  } catch(e) {}

  let semaforo = 'mas90';
  if (!esEquipo) {
    if (dias < 0) { fefoCounts.vencidos++; semaforo = 'vencidos'; }
    else if (dias <= 30) { fefoCounts.menos30++; semaforo = 'menos30'; }
    else if (dias <= 90) { fefoCounts.menos90++; semaforo = 'menos90'; }
    else { fefoCounts.mas90++; }
  }

  const loteObj = {
    id: idx + 1,
    sku,
    producto: prod,
    marca: marcaLimpia,
    es_equipo: esEquipo,
    lote_o_serie: rawLote,
    kits,
    pruebasU,
    vence: esEquipo ? 'N/A (Equipo Físico)' : venceStr,
    dias: esEquipo ? 9999 : dias,
    semaforo: esEquipo ? 'equipo_activo' : semaforo
  };

  productosStock[sku].lotes.push(loteObj);
  return loteObj;
});

