const invData = $('Mapear Inventario & Kardex 3FN').first()?.json || {};
const factData = $('Mapear Facturas DTE').first()?.json || {};
const pedData = $('Mapear Pedidos & Demanda').first()?.json || {};
const skuMap = $('Mapear Productos').first()?.json?.sku_map || {};

const productosStock = invData.productos_stock || {};
const demandaHist = factData.sku_demanda_historica || {};
const pedidosEnTransito = pedData.pedidos_en_transito_por_sku || {};

const listaAlertas = [];
let countCriticos = 0;
let countReorden = 0;
let countFefo = 0;
let countNormal = 0;
let montoTotalSugeridoUSD = 0;

for (const [sku, prod] of Object.entries(productosStock)) {
  const stockKits = prod.kits || 0;
  const stockPruebasU = prod.pruebasU || 0;
  const marca = prod.marca || 'Genérica';
  const nombre = skuMap[sku] || (prod.producto && prod.producto !== 'Reactivo Diagnóstico' ? prod.producto : null) || ('Reactivo ' + sku);

  // Demanda mensual estimada
  const demandaMes = Number(demandaHist[sku] || (stockKits > 0 ? Math.max(12, Math.round(stockKits * 0.28)) : 20));
  const consumoDiario = Math.max(0.1, Number((demandaMes / 30).toFixed(2)));

  const leadTimeDias = 30;
  const stockSeguridadKits = Math.ceil(consumoDiario * 15);
  const ropKits = Math.ceil((consumoDiario * leadTimeDias) + stockSeguridadKits);
  const stockMaximoKits = Math.ceil(consumoDiario * 90);

  const enTransitoKits = Number(pedidosEnTransito[sku] || 0);
  const balanceOfertaKits = stockKits + enTransitoKits;
  const diasCobertura = Math.round(stockKits / consumoDiario);

  let loteMasProximo = null;
  let minDias = 9999;
  if (prod.lotes && prod.lotes.length > 0) {
    for (const l of prod.lotes) {
      if (l.dias < minDias && l.kits > 0 && !l.es_equipo) {
        minDias = l.dias;
        loteMasProximo = l;
      }
    }
  }

  let nivelAlerta = 'NORMAL';
  let badgeColor = 'emerald';
  let accionSugerida = 'Inventario equilibrado. Monitoreo regular.';
  let sugeridoComprarKits = 0;

  if (stockKits <= stockSeguridadKits || diasCobertura <= 15) {
    nivelAlerta = 'CRITICO';
    badgeColor = 'rose';
    accionSugerida = 'Peligro de quiebre inminente (< 15 días cobertura). Emitir Orden Express.';
    sugeridoComprarKits = Math.max(0, stockMaximoKits - balanceOfertaKits);
    countCriticos++;
  } else if (balanceOfertaKits <= ropKits) {
    nivelAlerta = 'REORDEN';
    badgeColor = 'amber';
    accionSugerida = 'Punto de reorden alcanzado. Emitir Orden de Compra Programada.';
    sugeridoComprarKits = Math.max(0, stockMaximoKits - balanceOfertaKits);
    countReorden++;
  } else if (loteMasProximo && loteMasProximo.dias <= 90 && loteMasProximo.kits > (consumoDiario * loteMasProximo.dias)) {
    nivelAlerta = 'RIESGO_FEFO';
    badgeColor = 'indigo';
    accionSugerida = 'Riesgo de caducidad. Despacho prioritario FEFO o promoción.';
    countFefo++;
  } else {
    countNormal++;
  }

  const costoUnitarioEstimado = 42.50;
  const costoTotalSugerido = sugeridoComprarKits * costoUnitarioEstimado;
  montoTotalSugeridoUSD += costoTotalSugerido;

  listaAlertas.push({
    sku,
    producto: nombre,
    marca,
    stock_actual_kits: stockKits,
    stock_actual_pruebas_u: stockPruebasU,
    pedidos_en_transito_kits: enTransitoKits,
    consumo_diario_kits: consumoDiario,
    dias_cobertura: diasCobertura,
    stock_seguridad_kits: stockSeguridadKits,
    rop_kits: ropKits,
    stock_maximo_kits: stockMaximoKits,
    sugerido_comprar_kits: sugeridoComprarKits,
    costo_estimado_usd: costoTotalSugerido,
    nivel_alerta: nivelAlerta,
    badge_color: badgeColor,
    lote_proximo: loteMasProximo ? { lote: loteMasProximo.lote_o_serie, vence: loteMasProximo.vence, dias: loteMasProximo.dias, kits: loteMasProximo.kits } : null,
    accion_sugerida: accionSugerida,
    fecha_evaluacion: new Date().toISOString()
  });
}

listaAlertas.sort((a, b) => {
  const score = { 'CRITICO': 3, 'REORDEN': 2, 'RIESGO_FEFO': 1, 'NORMAL': 0 };
  return (score[b.nivel_alerta] || 0) - (score[a.nivel_alerta] || 0);
});

return [{
  json: {
    tipo: 'alertas_oferta_demanda',
    timestamp: new Date().toISOString(),
    resumen: {
      total_evaluados: Object.keys(productosStock).length,
      total_alertas_activas: countCriticos + countReorden + countFefo,
      quiebres_inminentes_criticos: countCriticos,
      reorden_sugerido: countReorden,
      riesgo_fefo_caducidad: countFefo,
      inventario_normal: countNormal,
      monto_total_sugerido_usd: Number(montoTotalSugeridoUSD.toFixed(2))
    },
    alertas: listaAlertas
  }
}];

